<?php
use Modules\Woocommerce\Models\WooCommerceWebhookReceipt;use Modules\Woocommerce\Models\WoocommerceSetting;
require dirname(__DIR__,4).'/vendor/autoload.php';$app=require dirname(__DIR__,4).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();$expected=getenv('SALEPRO_EXPECTED_TEST_DB')?:'';if(!app()->environment('testing')||!in_array($expected,['salepro_webhook_clean','salepro_webhook_upgrade'],true)||DB::selectOne('SELECT DATABASE() AS db')->db!==$expected)exit(70);
$setting=WoocommerceSetting::query()->create(['sync_enabled'=>true,'webhook_secret_current'=>'synthetic-recovery-secret','webhook_key_version'=>1]);$dir=dirname(__DIR__,4).'/scratch/woo-recovery-'.bin2hex(random_bytes(5));mkdir($dir,0777,true);$worker=__DIR__.'/concurrent_recovery_worker.php';
$make=function(string $delivery)use($setting){$body='{"id":700,"date_modified_gmt":"2026-09-12T10:00:00Z"}';return WooCommerceWebhookReceipt::query()->create(['public_id'=>(string)Illuminate\Support\Str::uuid(),'woocommerce_setting_id'=>$setting->id,'delivery_id'=>$delivery,'topic'=>'order.updated','resource'=>'order','event'=>'updated','external_entity_id'=>'700','received_at'=>now(),'payload_sha256'=>hash('sha256',$body),'payload'=>$body,'payload_bytes'=>strlen($body),'signature_key_version'=>1,'status'=>'failed_retryable','next_attempt_at'=>now()->subSecond()]);};
$run=function($name,$modes)use($make,$dir,$worker){foreach(glob($dir.'/ready-*')?:[]as$f)unlink($f);$r=$make('recovery-'.$name);$ps=[];foreach($modes as$i=>$mode){$pipes=[];$p=proc_open([PHP_BINARY,$worker,(string)$r->id,$mode,$dir,(string)($i+1)],[['pipe','r'],['pipe','w'],['pipe','w']],$pipes,dirname(__DIR__,4));$ps[]=[$p,$pipes];if($i===0){$d=microtime(true)+15;while(!is_file($dir.'/ready-1')){if(microtime(true)>$d)throw new RuntimeException('bootstrap timeout');usleep(10000);}}}$out=[];foreach($ps as[$p,$pipes]){fclose($pipes[0]);$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$e=proc_close($p);if($e!==0)throw new RuntimeException("worker {$e}: {$stderr}");$out[]=json_decode($stdout,true,32,JSON_THROW_ON_ERROR);}return['race'=>$name,'outcomes'=>array_column($out,'outcome'),'jobs'=>array_sum(array_column($out,'jobs')),'receipts'=>WooCommerceWebhookReceipt::query()->where('woocommerce_setting_id',$r->woocommerce_setting_id)->where('delivery_id',$r->delivery_id)->count(),'attempts'=>$r->fresh()->dispatch_attempt_count,'overlap'=>min(array_column($out,'finished'))>max(array_column($out,'started'))];};
try{$proof=[$run('two-workers',['recover','recover']),$run('redelivery',['recover','redeliver'])];echo json_encode($proof,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR),PHP_EOL;foreach($proof as$row)if(!$row['overlap']||$row['jobs']!==1||$row['receipts']!==1||$row['attempts']!==1)exit(1);}finally{WooCommerceWebhookReceipt::query()->where('woocommerce_setting_id',$setting->id)->delete();$setting->delete();foreach(glob($dir.'/*')?:[]as$f)unlink($f);rmdir($dir);}
